import * as AasTypes from "../src/types";
import * as TestCommonJsonization from "./commonJsonization";

test("casts over an instance of Something", () => {
  const theSomething =
    TestCommonJsonization.loadMinimalSomething();

  expect(
    AasTypes.isSomething(theSomething)
  ).toStrictEqual(true);
  expect(
    AasTypes.asSomething(theSomething)
  ).toStrictEqual(theSomething);

  expect(
    AasTypes.isCollection(theSomething)
  ).toStrictEqual(false);
  expect(
    AasTypes.asCollection(theSomething)
  ).toBeNull();
});

test("casts over an instance of Collection", () => {
  const theCollection =
    TestCommonJsonization.loadMinimalCollection();

  expect(
    AasTypes.isSomething(theCollection)
  ).toStrictEqual(false);
  expect(
    AasTypes.asSomething(theCollection)
  ).toBeNull();

  expect(
    AasTypes.isCollection(theCollection)
  ).toStrictEqual(true);
  expect(
    AasTypes.asCollection(theCollection)
  ).toStrictEqual(theCollection);
});

